select
  id, study_id, patient_id, exam_no, test_no, create_time, update_time, result_time, abnormal_indicator_high, abnormal_indicator_low, direct_bilirubin, creatinine, blood_urea_nitrogen, serum_cystatin_c, carbon_dioxide, uric_acid, microglobulinβ2
from td_renal_function_items


        and id = #{id}


        and study_id = #{studyId}


        and patient_id = #{patientId}


        and exam_no = #{examNo}


        and test_no = #{testNo}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and result_time = #{resultTime}


        and abnormal_indicator_high = #{abnormalIndicatorHigh}


        and abnormal_indicator_low = #{abnormalIndicatorLow}


        and direct_bilirubin = #{directBilirubin}


        and creatinine = #{creatinine}


        and blood_urea_nitrogen = #{bloodUreaNitrogen}


        and serum_cystatin_c = #{serumCystatinC}


        and carbon_dioxide = #{carbonDioxide}


        and uric_acid = #{uricAcid}


        and microglobulinβ2 = #{microglobulinβ2}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from td_renal_function_items


